INSERT INTO "PUBLIC"."ESTANDE_TIRO" VALUES
(2, '/assets/cenarios/2.png', TIMESTAMP '2026-11-20 21:02:23.241945', U&'Voc\00ea se posiciona diante de um balc\00e3o de carvalho enegrecido, em meio ao vasto e g\00e9lido sal\00e3o de pedra coroado por arcos ogivais e tape\00e7arias carcomidas. \00c0 penumbra, colunas imponentes projetam sombras longas, enquanto velas tr\00eamulas em candelabros de ferro lutam contra a escurid\00e3o que emana do piso de lajotas irregulares. Entre armaduras vazias que parecem vigiar cada movimento seu, rel\00e2mpagos cortam a noite atrav\00e9s de um vitral destro\00e7ado ao fundo, revelando alvos grotescos que se erguem e desaparecem sorrateiramente al\00e9m do pesado port\00e3o de ferro.', 'REALISTA', U&'Sal\00e3o do Castelo', U&'Cen\00e1rio de fundo 2D para minigame de estande de tiro, vis\00e3o em primeira pessoa olhando para o fundo do estande. Vasto e g\00e9lido sal\00e3o de um castelo g\00f3tico, com paredes de pedra cinzenta \00famida, colunas imponentes, arcos ogivais, tape\00e7arias carcomidas e velas tr\00eamulas em pesados candelabros de ferro nas laterais. Balc\00e3o inferior com tampo de carvalho enegrecido e base de pedra em primeiro plano. \00c1rea central VAZIA, com piso de lajotas de pedra irregulares e trilhos met\00e1licos paralelos no ch\00e3o, onde os alvos v\00e3o deslizar; ao fundo, um grande vitral destro\00e7ado iluminado por rel\00e2mpagos e um pesado port\00e3o de ferro. Clima de terror e suspense com sombras longas e ilumina\00e7\00e3o dram\00e1tica. Sem personagens, sem pessoas, sem alvos, sem armas, sem texto, sem logotipos. Estilo realista, propor\00e7\00e3o 16:9.', 'CASTELO'),
(3, '/assets/cenarios/3.png', TIMESTAMP '2026-11-20 21:02:23.24494', U&'Enclausurado no bunker de concreto bruto, o estande de tiro vibra sob as vigas de a\00e7o expostas e o zumbido irritante de holofotes frios que piscam sobre sacos de areia e caixotes militares empilhados. No primeiro plano, o balc\00e3o de chapa de a\00e7o com faixas de alerta amarelas e pretas delimita seu espa\00e7o, enquanto a luz vermelha de emerg\00eancia banha o piso de concreto manchado de \00f3leo. Ao fundo, diante da parede crivada de balas e da sinistra porta blindada entreaberta, silhuetas distorcidas come\00e7am a surgir e sumir na penumbra, \00e0 espreita entre as grades met\00e1licas.', 'CARTOON', 'Hangar da Ilha', U&'Cen\00e1rio de fundo 2D para minigame de estande de tiro, vis\00e3o em primeira pessoa olhando para o fundo do estande, ambientado em um estande de treinamento dentro de um bunker de concreto bruto na ilha, com vigas de a\00e7o expostas, sacos de areia, caixotes militares empilhados, grades met\00e1licas e holofotes de luz fria piscando junto com luzes de emerg\00eancia vermelhas criando um clima de terror e suspense. Balc\00e3o de chapa de a\00e7o com faixas de alerta amarelas e pretas em primeiro plano na parte inferior. \00c1rea central totalmente vazia, com piso de concreto manchado de \00f3leo e trilhos paralelos com suportes vazios onde os alvos v\00e3o aparecer. Ao fundo, uma parede de concreto crivada de marcas de tiros e uma sinistra porta blindada entreaberta na penumbra. Sem personagens, sem pessoas, sem alvos, sem armas, sem texto, sem logotipos. Estilo cartoon, propor\00e7\00e3o 16:9.', 'BASE_MILITAR'),
(4, '/assets/cenarios/4.png', TIMESTAMP '2026-11-20 21:02:23.246941', U&'O estande de tiro se estende por um galp\00e3o subterr\00e2neo abafado, onde paredes de rocha \00famida e vigas de madeira rangem pesadamente sob o peso da terra. A fraca e tr\00eamula luz de lampi\00f5es a \00f3leo corta a penumbra, projetando sombras longas sobre trilhos de vagonete cobertos de ferrugem que cortam o ch\00e3o de ponta a ponta. Ao fundo, um painel em pixel art retrata um labirinto escuro de t\00faneis de mina, onde lanternas oscilantes revelam alvos de madeira que surgem e somem sorrateiramente entre os ecos distantes de gemidos na rocha.', 'PIXEL_ART', U&'Po\00e7o da Mina', U&'Cen\00e1rio de fundo 2D para minigame de estande de tiro, vis\00e3o em primeira pessoa olhando para o fundo do estande em um galp\00e3o subterr\00e2neo e abafado. Paredes de rocha \00famida e bruta escoradas por vigas de madeira pesadas, enfeitadas com caixotes de dinamite, correntes enferrujadas e lanternas a \00f3leo penduradas que projetam uma luz fraca e tr\00eamula cortando a penumbra. Balc\00e3o improvisado com t\00e1buas grossas sobre caixotes de madeira em primeiro plano na parte inferior. \00c1rea central completamente vazia, com ch\00e3o de cascalho cinzento cortado por trilhos de vagonete paralelos e suportes met\00e1licos vazios por onde os alvos v\00e3o deslizar. Ao fundo, a boca escura de um t\00fanel de mina abandonado com um vagonete enferrujado e trilhos sumindo na escurid\00e3o. Sem personagens, sem pessoas, sem alvos, sem armas, sem texto, sem logotipos. Estilo pixel art detalhado, propor\00e7\00e3o 16:9.', 'MINA');           
INSERT INTO "PUBLIC"."ESTANDE_TIRO" VALUES
(65, '/assets/cenarios/65.png', TIMESTAMP '2026-11-23 20:58:44.387037', U&'No interior abafado do celeiro r\00fastico de madeira escura, fardos de feno, ferramentas agr\00edcolas e r\00e9stias de alho dividem o espa\00e7o sob a luz tr\00eamula de lampi\00f5es a \00f3leo amarelados. O jogador apoia as m\00e3os sobre o balc\00e3o de madeira gasta, observando a terra batida coberta de palha que se estende pelo ch\00e3o sombrio. Atrav\00e9s das portas abertas ao fundo, avista-se a vila rural sob um c\00e9u nublado de fim de tarde, onde a silhueta de casas de pedra e a torre de uma igreja se recortam na penumbra. Nesse cen\00e1rio sufocante, alvos grotescos surgem e somem de repente entre as sombras, acompanhados por rangidos met\00e1licos e sussurros distantes que ecoam no teto de vigas.', 'PIXEL_ART', 'Galpap da vila', U&'Cen\00e1rio de fundo 2D para minigame de estande de tiro, vis\00e3o em primeira pessoa olhando para o fundo do estande. Ambienta\00e7\00e3o vila rural europeia: interior abafado de celeiro r\00fastico de madeira escura com teto de vigas, fardos de feno, ferramentas agr\00edcolas e r\00e9stias de alho penduradas, iluminado por lampi\00f5es a \00f3leo amarelados, clima de terror e suspense. Balc\00e3o de madeira gasta em primeiro plano na parte inferior. \00c1rea central VAZIA, com ch\00e3o de terra batida coberto de palha e trilhos paralelos com suportes vazios onde os alvos v\00e3o aparecer; ao fundo, as portas abertas do celeiro mostram a vila sob um c\00e9u nublado de fim de tarde, com casas de pedra, telhados de palha e a torre de uma igreja. Sem personagens, sem pessoas, sem alvos, sem armas, sem texto, sem logotipos. Estilo pixel art, propor\00e7\00e3o 16:9.', 'VILA_RURAL'),
(66, '/assets/cenarios/66.png', TIMESTAMP '2026-11-23 20:59:29.417494', U&'Voc\00ea se apoia sobre o balc\00e3o de madeira gasta dentro do celeiro escuro, iluminado apenas pela luz tr\00eamula', 'REALISTA', 'vila', U&'Cen\00e1rio de fundo 2D para minigame de estande de tiro, vis\00e3o em primeira pessoa olhando para o fundo do estande. Ambienta\00e7\00e3o vila rural europeia: interior de um celeiro r\00fastico de madeira escura e envelhecida com teto alto de vigas aparentes, fardos de feno empilhados, foices e forcados enferrujados nas paredes, e r\00e9stias de alho penduradas, iluminado pela luz tr\00eamula e amarelada de lampi\00f5es a \00f3leo nas paredes. Balc\00e3o de madeira gasta e texturizada em primeiro plano na parte inferior. \00c1rea central completamente VAZIA, com ch\00e3o de terra batida coberto de palha seca e trilhos met\00e1licos paralelos e suportes vazios no ch\00e3o por onde os alvos v\00e3o aparecer; ao fundo, as grandes portas duplas abertas do celeiro emolduram a vis\00e3o da vila sob um c\00e9u nublado de fim de tarde, revelando casas de pedra r\00fastica, telhados de palha e a silhueta da torre de uma igreja ao longe. Sem personagens, sem pessoas, sem alvos, sem armas, sem texto, sem logotipos. Estilo realista, propor\00e7\00e3o 16:9.', 'VILA_RURAL'),
(97, NULL, TIMESTAMP '2026-11-23 22:46:33.240447', 'No vast', 'REALISTA', 'vila', U&'Cen\00e1rio de fundo 2D para minigame de estande de tiro, vis\00e3o em primeira pessoa olhando para o fundo do grande sal\00e3o de um castelo g\00f3tico com paredes de pedra cinzenta escura, teto abobadado com arcos ogivais, pesadas tape\00e7arias vermelhas e rasgadas nas paredes laterais, candelabros de ferro forjado com velas derretidas e chamas tr\00eamulas, e armaduras de placas medievais vazias flanqueando o espa\00e7o. Em primeiro plano na parte inferior, um balc\00e3o r\00fastico com base de pedra esculpida e tampo de madeira de carvalho escura envelhecida. A \00e1rea central \00e9 totalmente vazia, composta por um piso de lajotas de pedra \00famidas com sulcos e trilhos met\00e1licos paralelos no ch\00e3o e discretos suportes mec\00e2nicos vazios onde os alvos ir\00e3o aparecer. Ao fundo, um imponente vitral g\00f3tico com vidro escuro estilha\00e7ado, iluminado por clar\00f5es dram\00e1ticos de rel\00e2mpagos vindos de uma tempestade externa, revelando um pesado port\00e3o de ferro trabalhado. Atmosfera sombria e g\00f3tica com ilumina\00e7\00e3o dram\00e1tica de tochas e raios. Sem personagens, sem pessoas, sem alvos, sem armas, sem texto, sem logotipos, estilo realista, propor\00e7\00e3o 16:9.', 'CASTELO');        
INSERT INTO "PUBLIC"."ESTANDE_TIRO" VALUES
(98, NULL, TIMESTAMP '2026-11-23 22:47:01.122001', U&'O estande de tiro ocupa o grande sal\00e3o de um castelo g\00f3tico, onde paredes de pedra \00famida e colunas com arcos ogivais guardam tape\00e7arias rasgadas e armaduras decorativas que parecem espreitar nas sombras. Em primeiro plano, um balc\00e3o de pedra com tampo de madeira escura entalhada aguarda o jogador, enquanto velas tr\00eamulas em candelabros de ferro lan\00e7am uma luz fraca e dan\00e7ante sobre o piso de lajotas frias. Ao fundo, para al\00e9m de um pesado port\00e3o de ferro, um enorme vitral escuro \00e9 cortado por rel\00e2mpagos intermitentes que revelam, por fra\00e7\00f5es de segundo, alvos grotescos surgindo e sumindo na escurid\00e3o.', 'REALISTA', 'd', U&'Cen\00e1rio de fundo 2D para minigame de estande de tiro em estilo realista, vis\00e3o em primeira pessoa. O ambiente \00e9 o interior do grande sal\00e3o de um castelo g\00f3tico, com paredes de pedra \00famida, colunas robustas sustentando arcos ogivais, tape\00e7arias cinzentas rasgadas e armaduras decorativas de ferro enegrecido posicionadas nas laterais sob uma ilumina\00e7\00e3o sombria de velas tr\00eamulas em candelabros de ferro. Em primeiro plano na parte inferior, h\00e1 um balc\00e3o feito de blocos de pedra e tampo de madeira escura entalhada. A \00e1rea central est\00e1 completamente vazia e livre, composta por piso de lajotas de pedra desgastadas e trilhos met\00e1licos paralelos com suportes vazios para deslizamento de alvos. Ao fundo, destaca-se um pesado port\00e3o de ferro e um imenso vitral escuro e estilha\00e7ado, iluminado dramaticamente por rel\00e2mpagos vindos de uma tempestade externa. Sem personagens, sem pessoas, sem alvos, sem armas, sem texto, sem logotipos, propor\00e7\00e3o 16:9.', 'CASTELO');        
INSERT INTO "PUBLIC"."ALVO_INIMIGO" VALUES
(1, '/assets/alvos/1.png', 'COMUM', TIMESTAMP '2026-11-23 20:14:15.98533', U&'campon\00eas hostil de uma vila europeia antiga, de boina escura, camisa de linho surrada e cal\00e7a de lona, segurando um forcado na diagonal \00e0 frente do corpo', 0, U&'Alde\00e3o com forcado', 'VILA_RURAL'),
(2, '/assets/alvos/2.png', 'COMUM', TIMESTAMP '2026-11-23 20:14:35.668881', U&'campon\00eas hostil de uma vila europeia antiga, de colete marrom e boina, segurando uma tocha acesa ao lado do corpo', 1, U&'Alde\00e3o com tocha', 'VILA_RURAL'),
(3, '/assets/alvos/3.png', 'AGIL', TIMESTAMP '2026-11-23 20:14:40.353861', U&'camponesa hostil de uma vila europeia antiga, com len\00e7o na cabe\00e7a, blusa surrada e saia longa escura, segurando uma foice ao lado do corpo', 2, U&'Alde\00e3 com foice', 'VILA_RURAL'),
(4, '/assets/alvos/4.png', 'FORTE', TIMESTAMP '2026-11-23 20:14:46.883141', U&'lenhador hostil, alto, robusto e barbudo, de colete de couro e camisa encardida, segurando um machado grande com as duas m\00e3os \00e0 frente do corpo', 3, 'Lenhador com machado', 'VILA_RURAL'),
(5, NULL, 'COMUM', NULL, 'cultista encapuzado de manto roxo escuro, com o rosto na sombra do capuz, segurando um cajado de madeira com uma pedra roxa na ponta', 0, 'Cultista com cajado', 'CASTELO'),
(6, NULL, 'AGIL', NULL, 'cultista encapuzado de manto vermelho escuro, com o rosto na sombra do capuz, segurando uma foice', 1, 'Cultista com foice', 'CASTELO'),
(7, NULL, 'FORTE', NULL, U&'guardi\00e3o de manto preto com m\00e1scara branca lisa, segurando um escudo de metal e um bast\00e3o', 2, U&'Guardi\00e3o mascarado', 'CASTELO'),
(8, NULL, 'COMUM', NULL, U&'soldado de uniforme verde-oliva, capacete e m\00e1scara de g\00e1s, segurando um cassetete', 0, 'Soldado com cassetete', 'BASE_MILITAR'),
(9, NULL, 'AGIL', NULL, U&'soldado \00e1gil de uniforme verde-oliva, capacete e m\00e1scara de g\00e1s, segurando uma faca de combate', 1, 'Soldado com faca', 'BASE_MILITAR'),
(10, NULL, 'FORTE', NULL, U&'soldado pesado de armadura cinza, capacete e m\00e1scara de g\00e1s, segurando um escudo antimotim e uma marreta', 2, 'Soldado pesado com escudo', 'BASE_MILITAR'),
(11, '/assets/alvos/11.png', 'COMUM', TIMESTAMP '2026-11-23 22:45:37.243985', U&'mineiro possu\00eddo de capacete amarelo com lanterna e roupas sujas de carv\00e3o, segurando uma picareta', 0, 'Mineiro com picareta', 'MINA'),
(12, NULL, 'AGIL', NULL, U&'mineiro possu\00eddo de capacete amarelo com lanterna, segurando uma banana de dinamite de pavio aceso', 1, 'Mineiro com dinamite', 'MINA'),
(13, NULL, 'FORTE', NULL, 'minerador brutamontes, enorme e barbudo, de avental de couro, segurando uma marreta pesada', 2, 'Brutamontes com marreta', 'MINA'),
(14, NULL, 'COMUM', NULL, 'pirata sombrio de bandana vermelha e camisa listrada, segurando um sabre curvo', 0, 'Pirata com sabre', 'PORTO'),
(15, NULL, 'AGIL', NULL, U&'marujo sombrio de bandana azul e camisa listrada, com um gancho de metal no lugar de uma das m\00e3os', 1, 'Marujo com gancho', 'PORTO'),
(16, NULL, 'FORTE', NULL, U&'capit\00e3o pirata sombrio, alto e barbudo, de casaco longo escuro e chap\00e9u tric\00f3rnio, segurando um sabre', 2, U&'Capit\00e3o pirata', 'PORTO'),
(33, '/assets/alvos/33.png', 'REFEM', TIMESTAMP '2026-11-23 20:40:10.931419', U&'jovem ref\00e9m assustada de uma vila europeia antiga, de cabelo castanho-escuro preso em rabo de cavalo, blusa de linho branca, colete azul-marinho e saia longa azul, com as m\00e3os amarradas \00e0 frente por uma corda grossa', -1, U&'Ref\00e9m da vila', 'VILA_RURAL'),
(34, '/assets/alvos/34.png', 'REFEM', TIMESTAMP '2026-11-23 22:46:00.415227', U&'jovem ref\00e9m assustada, de cabelo preto preso em tran\00e7a, vestido longo e simples cinza-claro de criada de castelo, com as m\00e3os amarradas \00e0 frente por uma corda grossa', -1, U&'Ref\00e9m do castelo', 'CASTELO'),
(35, '/assets/alvos/35.png', 'REFEM', TIMESTAMP '2026-11-23 22:45:53.003642', U&'jovem ref\00e9m assustada, de cabelo ruivo curto, macac\00e3o laranja de prisioneira, com as m\00e3os presas \00e0 frente por uma bra\00e7adeira de pl\00e1stico', -1, U&'Ref\00e9m da base', 'BASE_MILITAR');   
INSERT INTO "PUBLIC"."ALVO_INIMIGO" VALUES
(36, '/assets/alvos/36.png', 'REFEM', TIMESTAMP '2026-11-23 22:45:45.768677', U&'jovem ref\00e9m assustada, de cabelo castanho preso em coque, camisa xadrez, cal\00e7a de trabalho e rosto sujo de carv\00e3o, com as m\00e3os amarradas \00e0 frente por uma corda grossa', -1, U&'Ref\00e9m da mina', 'MINA'),
