-- H2 2.3.232;
CREATE CACHED TABLE "PUBLIC"."ESTANDE_TIRO"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 99) NOT NULL,
    "CAMINHO_IMAGEM" CHARACTER VARYING(255),
    "DATA_CRIACAO" TIMESTAMP(6) NOT NULL,
    "DESCRICAO_GERADA_POR_IA" CHARACTER VARYING(2000),
    "ESTILO_VISUAL" CHARACTER VARYING(20) NOT NULL,
    "NOME" CHARACTER VARYING(80) NOT NULL,
    "PROMPT_IMAGEM" CHARACTER VARYING(4000),
    "TIPO" CHARACTER VARYING(30) NOT NULL
);         
ALTER TABLE "PUBLIC"."ESTANDE_TIRO" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_5" PRIMARY KEY("ID"); 
-- 7 +/- SELECT COUNT(*) FROM PUBLIC.ESTANDE_TIRO;            
CREATE CACHED TABLE "PUBLIC"."ALVO_INIMIGO"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 65) NOT NULL,
    "CAMINHO_IMAGEM" CHARACTER VARYING(255),
    "CLASSE" CHARACTER VARYING(10) NOT NULL,
    "DATA_IMAGEM" TIMESTAMP(6),
    "DESCRICAO_VISUAL" CHARACTER VARYING(400) NOT NULL,
    "INDICE_DESENHO" INTEGER NOT NULL,
    "NOME" CHARACTER VARYING(60) NOT NULL,
    "TIPO_ESTANDE" CHARACTER VARYING(30) NOT NULL
);       
ALTER TABLE "PUBLIC"."ALVO_INIMIGO" ADD CONSTRAINT "PUBLIC"."CONSTRAINT_2" PRIMARY KEY("ID"); 
